input.script:
users = list_users({})
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

by_date = for date in dates {
    busies = for u in users {
        a = boundary retry 2 {
            return get_availability({ user_id: u.id, date })
        } catch err {
            return fail("AVAIL", err.code + ": " + err.message)
        }
        return a.busy
    }
    all_busy = fold acc = [] for b in busies { return acc + b }
    free = for i in list.range(0, 15) {
        s = 540 + i * 30
        e = s + 60
        conflict = fold acc = false for b in all_busy {
            bs = number.parse(text.slice(b.start, 0, 2)) * 60 + number.parse(text.slice(b.start, 3, 5))
            be = number.parse(text.slice(b.end, 0, 2)) * 60 + number.parse(text.slice(b.end, 3, 5))
            return acc or (s < be and bs < e)
        }
        skip if conflict
        return s
    }
    skip if free == []
    return { date: date, start: free[0] }
}

first = by_date[0] if by_date != [] else fail("NONE", "no free 60-min slot in the week")
s = first.start
e = s + 60
sh = number.floor(s / 60)
sm = s - sh * 60
eh = number.floor(e / 60)
em = e - eh * 60
shs = if sh < 10 { return "0" + json.encode(sh) } else { return json.encode(sh) }
sms = if sm < 10 { return "0" + json.encode(sm) } else { return json.encode(sm) }
ehs = if eh < 10 { return "0" + json.encode(eh) } else { return json.encode(eh) }
ems = if em < 10 { return "0" + json.encode(em) } else { return json.encode(em) }
start_iso = first.date + "T" + shs + ":" + sms + ":00Z"
end_iso = first.date + "T" + ehs + ":" + ems + ":00Z"
r = submit_result({ answer: { start: start_iso, end: end_iso } })
return { start: start_iso, end: end_iso, submitted: r.recorded }
